findings.repro_r:
local({
  path <- tempfile(fileext = ".html")
  on.exit(unlink(path))
  result <- tryCatch(sas2r::sas_print_table(data.frame(value = c(1, 2)), path), error = identity)
  if (file.exists(path) && identical(readBin(path, "raw", n = 5L), charToRaw("%PDF-")))
    stop("Reproduced: the helper wrote PDF bytes to a non-PDF destination.")
  stopifnot(inherits(result, "error"), !file.exists(path))
  stopifnot(grepl("file must end in .pdf", conditionMessage(result), fixed = TRUE))
  message("The helper rejected the destination before writing a file.")
})
